<?php
namespace App\Http\Controllers\Backend;
use App\Helpers\ResponseHelper;use App\Http\Controllers\Controller;use App\Http\Requests\Accounts\VoucherRequest;use App\Models\LedgerAccount;use App\Models\Voucher;use App\Services\VoucherService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;use Illuminate\View\View;use Yajra\DataTables\Facades\DataTables;
class VoucherController extends Controller{public function index(Request $r):View|JsonResponse{Gate::authorize('accounts.view');if($r->ajax())return DataTables::eloquent(Voucher::withCount('lines')->forActiveShop()->when($r->filled('type'),fn($q)=>$q->where('type',$r->string('type'))))->addIndexColumn()->editColumn('voucher_date',fn($x)=>$x->voucher_date->format('d-m-Y'))->editColumn('total_debit',fn($x)=>number_format((float)$x->total_debit,2))->toJson();return view('backend.accounts.vouchers',['accounts'=>LedgerAccount::where(fn($q)=>$q->whereNull('shop_id')->orWhere('shop_id',session('active_shop_id')))->where('is_active',true)->get(['id','name','code'])]);}public function store(VoucherRequest $r,VoucherService $s):JsonResponse{return ResponseHelper::success('Voucher posted successfully.',$s->create($r->validated()),201);}}
